ITEMS = {}
for part, raw in [(22, PART22), (23, PART23)]:
    for line in raw.strip().splitlines():
        cells = line.split('|')
        assert len(cells) == 8, (part, cells[0], len(cells))
        number, topic, lead, interpretation, *reasons = cells
